-    for l in loops {
-        let n = l.len() as f64;
-        let c = l.iter().fold(p(0., 0., 0.), |s, q| p(s.x + q.x / n, s.y + q.y / n, s.z + q.z / n));
-        for i in 0..l.len() {
-            tris.push(Triangle::new(c, l[i], l[(i + 1) % l.len()]));
-        }
-        ends.push(tris.len());
-    }
-    (tris, ends)
-}
