+    let r = within(HANG_BARRIER, || {
+        import::load_model(&testdata("bspline_discontinuous.step"))
+    });
+    let err = r.expect_err("refused").to_string();
+    assert!(err.contains("face #53") && err.contains("off the face's surface"), "{err}");
+}
