+/// `solid #12 'bracket'`, or `solid #12` for a solid without a name.
+#[cfg(not(target_arch = "wasm32"))]
+fn solid_label(item: u64, name: &str) -> String {
+    if name.is_empty() {
+        format!("solid #{item}")
+    } else {
+        format!("solid #{item} '{name}'")
+    }
+}

